import React from "react";

// First-visit splash. Rendered straight into the server HTML (no client JS)
// so it's on screen before the banner's particle canvas and fade-ins have
// had a chance to run. Visibility is driven entirely by classes the inline
// SITE_LOADER_SCRIPT puts on <html> — without JS the splash never shows.

// Plain inline script, run from <head> before first paint:
// - first full page load of the session only (repeat reloads skip it)
// - lifts once `window.load` fires, but never before MIN so the logo
//   assembly finishes, and never later than MAX in case something hangs
export const SITE_LOADER_SCRIPT = `(function(){
  var d = document.documentElement;
  try {
    if (sessionStorage.getItem("xv-loaded")) return;
    sessionStorage.setItem("xv-loaded", "1");
  } catch (e) {}
  d.classList.add("xv-loading");
  var start = Date.now(), MIN = 1600, MAX = 6000, done = false;
  function finish() {
    if (done) return;
    done = true;
    d.classList.add("xv-loaded");
    setTimeout(function () { d.classList.remove("xv-loading", "xv-loaded"); }, 700);
  }
  function onLoad() { setTimeout(finish, Math.max(0, MIN - (Date.now() - start))); }
  if (document.readyState === "complete") onLoad();
  else window.addEventListener("load", onLoad);
  setTimeout(finish, MAX);
})();`;

